import http from 'node:http';
import { readFile } from 'node:fs/promises';
import { extname, join, normalize, sep } from 'node:path';

const args = process.argv.slice(2);
const port = Number((args.includes('--port') ? args[args.indexOf('--port') + 1] : 0) || 4321);
const host = (args.includes('--host') ? args[args.indexOf('--host') + 1] : '') || '127.0.0.1';
const upstream = process.env.CUA_SWE_EXTERNAL_SERVICE_ORIGIN || 'http://127.0.0.1:4675';
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };

function safeRelPath(url) {
  const rel = url === '/' ? 'index.html' : url.split('?')[0].slice(1);
  const norm = normalize(rel);
  if (norm.startsWith('..' + sep) || norm === '..' || norm.startsWith('/')) return 'index.html';
  return norm;
}

http.createServer(async (req, res) => {
  if (req.url.startsWith('/api/')) {
    try {
      const upstreamRes = await fetch(upstream + req.url, { method: req.method });
      res.writeHead(upstreamRes.status, {
        'content-type': upstreamRes.headers.get('content-type') || 'application/json',
      });
      res.end(Buffer.from(await upstreamRes.arrayBuffer()));
    } catch {
      res.writeHead(502, { 'content-type': 'application/json' });
      res.end('{"error":"channel service unavailable"}');
    }
    return;
  }
  const safe = safeRelPath(req.url);
  try {
    const file = await readFile(join(process.cwd(), safe));
    res.writeHead(200, { 'content-type': types[extname(safe)] || 'application/octet-stream' });
    res.end(file);
  } catch {
    const file = await readFile(join(process.cwd(), 'index.html'));
    res.writeHead(200, { 'content-type': 'text/html' });
    res.end(file);
  }
}).listen(port, host);

}

// The height of the band's solid bar, one part of the trailing region.
export function coverSize(v) {
  return v.coverSize;
}

// The resolved total the scroll track is sized to: the run of rows plus the
// reserved trailing footer region below them.
export function totalContentSize(v) {
  return measuredRunSize(v) + v.trailingSize;
}

// The scroll offset that brings a target row to rest at the desired place in
// the viewport. For the newest (last) entry the intent is that it comes to rest
// against the bottom edge of the viewport with nothing clipped and no gap left
// under it.
export function offsetToBringLast(v) {
  const lastTop = offsetForIndex(v, v.count - 1);
  const lastSize = sizeOf(v, v.count - 1);
  // The sticky footer overlays the viewport, so leave the full reserved
  // trailing band below the newest entry.
  return lastTop + lastSize + v.trailingSize - v.viewportHeight;
}

export function clampOffset(v, offset) {
  const max = totalContentSize(v) - v.viewportHeight;
  if (offset < 0) return 0;
  if (offset > max) return max;
  return offset;
}

